/**
 * Coaches Intel — Google Sheets + Apps Script web app.
 * The spreadsheet is the database:
 *   Coaches, Schools          the directory (edit freely; changes show on the next app load)
 *   Messages, Statuses, Offers, X Posts, Recruits, Coach Edits, School Edits, Profile
 *                             written by the app (one row per record, readable columns + a JSON column)
 *   Settings                  optional Anthropic API key for the AI reply assistant
 *   Users, Logins, Events     who signs in, when, from what device, how fast the app loads, what they use
 *   Usage Summary             live totals built from those tabs
 *
 * Every saved record carries the email of the person who made it, so each signed-in user only sees their own.
 * Sign-in happens in the companion "Coaches Intel Sign-in" web app (runs as the visitor so Google confirms their
 * email); it talks to this project through doPost below using API_KEY.
 */
var API_KEY = 'htvGQEZCkmUXyc5zEeb61X07zb1kIEPL-VBVBjYkpiw';
var OWNER_EMAIL = 'drumaine@gmail.com';
var APP_BUILD = '2026.11.08-5';   // bump with each sign-in app deploy so open apps show the update notice

var STATE_TABS = {
  log:      { tab: 'Messages',     cols: ['at', 'aid', 'name', 'school', 'ch', 'dir', 'subj', 'body', 'note'] },
  rel:      { tab: 'Statuses',     cols: ['aid', 'cid', 'st', 'star', 'nt'] },
  offers:   { tab: 'Offers',       cols: ['aid', 'type', 'school', 'name', 'st', 'dl'] },
  xposts:   { tab: 'X Posts',      cols: ['aid', 'at', 'kind', 'text', 'url'] },
  athletes: { tab: 'Recruits',     cols: ['name', 'pos', 'cls', 'hs', 'city', 'x', 'removed'] },
  coaches:  { tab: 'Coach Edits',  cols: ['s', 'n', 'r', 'p', 'e', 'x', 'custom', 'deleted'] },
  schools:  { tab: 'School Edits', cols: ['n', 't', 'd', 'st', 'custom', 'deleted'] },
  meta:     { tab: 'Profile',      cols: ['name', 'pos', 'cls', 'hs', 'film', 'x'] }
};

var COACH_COLS  = [['id','ID'],['s','School'],['n','Name'],['r','Role'],['p','Phone'],['e','Email'],['x','X handle'],['pg','Staff page'],['dup','Also listed at'],['cs','Status'],['fs','First seen'],['dd','Left on'],['tr','Territory'],['eg','Responsiveness'],['en','Messages measured'],['vs','Contact check'],['vf','Verified on'],['vc','Contact sources'],['vn','Verify note']];
var SCHOOL_COLS = [['n','School'],['t','Team'],['m','Mascot'],['d','Division'],['dv','Division label'],['cf','Conference'],['st','State'],['w','Website'],['cp','Coaches page'],['sd','Staff directory']];

/* ---------- menu & setup ---------- */
function onOpen() {
  SpreadsheetApp.getUi().createMenu('Coaches Intel')
    .addItem('Set up / repair tabs', 'setup')
    .addItem('Open app link', 'showAppLink')
    .addItem('Refresh app data now', 'refreshAppData')
    .addSeparator()
    .addItem('Scan coaching staffs now', 'scanNow')
    .addItem('Turn on monthly staff scanning', 'installScanTrigger')
    .addToUi();
}

var SHEET_ID = '1GJGBe2eLC54Z76fJozmsQdK3qcuO8oSQwRm2WMGvqRg';

function setup() {
  var ss = ss_();
  PropertiesService.getScriptProperties().setProperty('SHEET_ID', ss.getId());
  Object.keys(STATE_TABS).forEach(function (k) { stateSheet_(k); });
  var set = ss.getSheetByName('Settings') || ss.insertSheet('Settings');
  if (set.getLastRow() === 0) {
    set.getRange(1, 1, 4, 2).setValues([
      ['Setting', 'Value'],
      ['Anthropic API key (optional, turns on the AI reply assistant)', ''],
      ['Claude model', 'claude-sonnet-5-5'],
      ['Data pulled', '2026-10-29']
    ]);
    set.setColumnWidth(1, 420); set.setColumnWidth(2, 360);
    set.getRange('A1:B1').setFontWeight('bold');
  }
  if (!ss.getSheetByName('Coaches') || !ss.getSheetByName('Schools')) loadDirectory_(ss);
  analyticsSheets_();
  try { ss.setSpreadsheetTimeZone(tz_()); } catch (e) {}
  plainSheet_('Coach Changes', CHANGE_HEAD); plainSheet_('Scan Log', SCANLOG_HEAD); coachSheet_();
  try { if (!ScriptApp.getProjectTriggers().some(function (t) { return t.getHandlerFunction() === 'scanCoaches'; })) installScanTrigger(); } catch (e) {}
  bump_(); clearSeedCache_();
  try { SpreadsheetApp.getUi().alert('Coaches Intel is set up. Next: Deploy > New deployment > Web app (Execute as: Me). Open the web app link on any phone, tablet or computer.'); } catch (e) {}
}

function showAppLink() {
  var url = ScriptApp.getService().getUrl();
  Logger.log(url);
  SpreadsheetApp.getUi().alert(url ? 'Web app link:\n' + url : 'Deploy first: Deploy > New deployment > Web app.');
}

/* Builds the Coaches and Schools tabs from the bundled directory (Seed.gs). */
function loadDirectory_(ss) {
  if (typeof SEED_B64 === 'undefined') throw new Error('Seed.gs is missing');
  var d = JSON.parse(Utilities.ungzip(Utilities.newBlob(Utilities.base64Decode(SEED_B64), 'application/x-gzip')).getDataAsString('UTF-8'));
  d.schools.forEach(function (o) { if (o.w && !o.cp) o.cp = o.w + '/sports/football/coaches'; if (o.w && !o.sd) o.sd = o.w + '/staff-directory'; if (!o.dv) o.dv = o.d; });
  d.coaches = d.c.map(function (r) { var o = {}; d.ck.forEach(function (k, i) { o[k] = r[i]; }); var sc = d.schools[o.s]; o.s = sc.n; if (!o.pg) o.pg = sc.cp || ''; return o; });
  [['Schools', SCHOOL_COLS, d.schools], ['Coaches', COACH_COLS, d.coaches]].forEach(function (t) {
    var sh = ss.getSheetByName(t[0]) || ss.insertSheet(t[0]);
    sh.clear();
    var rows = [t[1].map(function (c) { return c[1]; })].concat(t[2].map(function (o) { return t[1].map(function (c) { return o[c[0]] == null ? '' : String(o[c[0]]); }); }));
    sh.getRange(1, 1, rows.length, rows[0].length).setNumberFormat('@').setValues(rows);
    sh.getRange(1, 1, 1, rows[0].length).setFontWeight('bold').setBackground('#0B0C0E').setFontColor('#C6F432');
    sh.setFrozenRows(1);
  });
  var first = ss.getSheets()[0];
  if (first.getName() === 'Sheet1' && first.getLastRow() === 0) ss.deleteSheet(first);
}

/* ---------- web app ---------- */
function doGet(e) {
  if (e && e.parameter && (e.parameter.o || e.parameter.pp)) return pushGet_(e.parameter);
  if (e && e.parameter && e.parameter.v) return ftLanding_(e.parameter.v);
  var me = String(Session.getActiveUser().getEmail() || '').toLowerCase();
  if (me !== OWNER_EMAIL) return HtmlService.createHtmlOutput('<p style="font-family:sans-serif;padding:24px">This is the RecruitDirect data service. Open the RecruitDirect sign-in link instead.</p>').setTitle('RecruitDirect');
  if (!ss_().getSheetByName('Coaches')) setup();
  var t = HtmlService.createTemplateFromFile('Index');
  var pk = seedPacked_();
  t.boot = JSON.stringify({ seedGz: pk.gz, h: pk.h, user: { email: OWNER_EMAIL, owner: true } });
  recordSignIn_(OWNER_EMAIL, 0, 'owner link');
  return t.evaluate()
    .setTitle('RecruitDirect')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1, viewport-fit=cover')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

function ss_() {
  var id = PropertiesService.getScriptProperties().getProperty('SHEET_ID') || SHEET_ID;
  return id ? SpreadsheetApp.openById(id) : SpreadsheetApp.getActiveSpreadsheet();
}

function rowsAsObjects_(sh, map) {
  var v = sh.getDataRange().getValues();
  if (v.length < 2) return [];
  var head = v[0].map(String);
  var idx = map.map(function (m) { return head.indexOf(m[1]); });
  var out = [];
  for (var r = 1; r < v.length; r++) {
    var o = {}, any = false;
    for (var i = 0; i < map.length; i++) {
      if (idx[i] < 0) continue;
      var val = v[r][idx[i]];
      if (val !== '' && val !== null) { o[map[i][0]] = String(val).trim(); any = true; }
    }
    if (any) out.push(o);
  }
  return out;
}

function slug_(s) { return String(s).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''); }

function seedJson_(sp) {
  var ss = ss_(); sp = SPORT_KEYS_.indexOf(sp) > 0 ? sp : 'fb';
  var cfg = sportCfg_(sp);
  var schools = sp === 'fb' ? rowsAsObjects_(ss.getSheetByName('Schools'), SCHOOL_COLS) : bbSchools_(sp);
  var csh = ss.getSheetByName(cfg.coaches);
  var coaches = (csh ? rowsAsObjects_(csh, COACH_COLS) : []).filter(function (c) { return c.n && c.s; });
  var seen = {}, staffed = {};
  coaches.forEach(function (c) {
    if (!c.id) c.id = slug_(c.s).slice(0, 34) + '--' + slug_(c.n);
    while (seen[c.id]) c.id += '-x';
    seen[c.id] = 1;
    if (c.cs === 'departed') c.dep = shortDay_(c.dd) || '1'; else staffed[c.s] = 1;
    delete c.cs; delete c.dd;
    if (c.fs) c.fs = shortDay_(c.fs);
    if (c.eg) c.eg = Number(c.eg) || 0; if (c.en) c.en = Number(c.en) || 0;
    if (c.x && c.x.charAt(0) !== '@') c.x = '@' + c.x;
    /* contact double-check (Verify.gs): short codes keep the download small */
    if (c.vs) c.vs = VF_STATUS_CODE_[c.vs] || ''; if (!c.vs) { delete c.vs; delete c.vf; delete c.vc; delete c.vn; }
    else { c.vf = shortDay_(c.vf); if (c.vc) c.vc = String(c.vc).slice(0, 90); if (c.vn && c.vs !== 'v') c.vn = String(c.vn).slice(0, 160); else delete c.vn; }
  });
  schools.forEach(function (s) { if (!staffed[s.n]) s.np = 1; if (!s.dv) s.dv = s.d; });
  /* roster counts (Rosters.gs) and academic data (Academics.gs) for position need and academic fit */
  try { var RN = rnMap_(sp); schools.forEach(function (s) { var r = RN[s.n]; if (r) { s.rn = r.c; if (r.y) s.ry = r.y; } }); } catch (e) {}
  try { acAttach_(schools, coaches); } catch (e) {}
  var pulled = '';
  var set = ss.getSheetByName('Settings');
  if (set) { var v = set.getRange(1, 1, Math.max(set.getLastRow(), 1), 2).getValues(); v.forEach(function (r) { if (r[0] === 'Data pulled') pulled = r[1] instanceof Date ? Utilities.formatDate(r[1], Session.getScriptTimeZone(), 'MMM d, yyyy') : String(r[1]); }); }
  var scanned = ''; try { scanned = setting_('Last full staff scan'); } catch (e) {}
  if (sp !== 'fb') { pulled = ''; scanned = ''; try { scanned = setting_(cfg.setting); } catch (e) {} }
  return JSON.stringify({ sport: sp, schools: schools, coaches: coaches, pulled: pulled, scanned: shortDay_(scanned), changes: recentChanges_(ss, cfg.changes) }).replace(/<\//g, '<\\/');
}
/* The directory, gzipped and cached for 6 hours so sign-in doesn't rebuild it from the sheet each time.
   Cleared whenever the scanner or an edit changes the Coaches, Schools, Coach Changes or Settings tabs. */
var SEED_KEY = 'SEEDPK2';
function seedPacked_(sp) {
  sp = SPORT_KEYS_.indexOf(sp) > 0 ? sp : 'fb';
  var SEED_KEY = sp === 'fb' ? 'SEEDPK2' : 'SEEDPK2_' + sp;
  var c = CacheService.getScriptCache(), meta = c.get(SEED_KEY), i;
  if (meta) {
    var m = JSON.parse(meta), keys = [];
    for (i = 0; i < m.n; i++) keys.push(SEED_KEY + '_' + i);
    var got = c.getAll(keys), parts = keys.map(function (k) { return got[k]; });
    if (parts.every(function (x) { return x != null; })) return { h: m.h, gz: parts.join('') };
  }
  var json = seedJson_(sp);
  var gz = Utilities.base64Encode(Utilities.gzip(Utilities.newBlob(json, 'application/json')).getBytes());
  var h = Utilities.base64EncodeWebSafe(Utilities.computeDigest(Utilities.DigestAlgorithm.MD5, json, Utilities.Charset.UTF_8)).slice(0, 16);
  var put = {}, n = Math.ceil(gz.length / 90000);
  for (i = 0; i < n; i++) put[SEED_KEY + '_' + i] = gz.substr(i * 90000, 90000);
  put[SEED_KEY] = JSON.stringify({ h: h, n: n });
  try { c.putAll(put, 21600); } catch (e) {}
  return { h: h, gz: gz };
}
function clearSeedCache_() { try { CacheService.getScriptCache().removeAll(['SEEDPK2', 'SEEDPK2_mbb', 'SEEDPK2_wbb']); } catch (e) {} }
function refreshAppData() { clearSeedCache_(); seedPacked_(); bumpAll_(); try { SpreadsheetApp.getUi().alert('App data refreshed. Reopen the app to see the latest coaches.'); } catch (e) {} }
/* Simple trigger: hand edits to the directory tabs refresh the app's cached copy. */
function onEdit(e) {
  try {
    var n = e.range.getSheet().getName();
    if (/^(Coaches|Schools|Coach Changes|Settings|Coaches [MW]BB|Schools BB|Coach Changes [MW]BB)$/.test(n)) clearSeedCache_();
    var tabs = Object.keys(STATE_TABS).map(function (k) { return STATE_TABS[k].tab; });
    if (tabs.indexOf(n) >= 0) bumpAll_(); /* hand edits to saved records reach every open app */
  } catch (x) {}
}
function shortDay_(v) {
  if (!v) return '';
  if (Object.prototype.toString.call(v) === '[object Date]') return Utilities.formatDate(v, tz_(), 'yyyy-MM-dd');
  var s = String(v); var d = new Date(s);
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  return isNaN(d) ? s : Utilities.formatDate(d, tz_(), 'yyyy-MM-dd');
}
/* The last year of coaching changes (newest first, capped) for the app's Alert Center and coach timelines. */
function recentChanges_(ss, name) {
  var sh = ss.getSheetByName(name || 'Coach Changes'); if (!sh || sh.getLastRow() < 2) return [];
  var n = Math.min(sh.getLastRow() - 1, 2500);
  var v = sh.getRange(sh.getLastRow() - n + 1, 1, n, 11).getValues();
  var cut = Date.now() - 365 * 864e5, out = [];
  for (var i = v.length - 1; i >= 0; i--) {
    var r = v[i], t = shortDay_(r[0]); if (!t || Date.parse(t) < cut) continue;
    var o = { t: t, k: String(r[1]), s: String(r[2]), n: String(r[3]) };
    if (r[4]) o.r = String(r[4]); if (r[5]) o.o = String(r[5]); if (r[6]) o.v = String(r[6]); if (r[7]) o.fs = String(r[7]);
    if (r[8]) o.cid = String(r[8]); if (r[9]) o.fid = String(r[9]); if (r[10]) o.nt = String(r[10]);
    out.push(o);
  }
  return out;
}

/* ---------- live state ---------- */
function stateSheet_(col) {
  var def = STATE_TABS[col]; if (!def) throw new Error('Unknown collection ' + col);
  var ss = ss_();
  var sh = ss.getSheetByName(def.tab);
  if (!sh) {
    sh = ss.insertSheet(def.tab);
    var head = ['id', 'user', 'updated'].concat(def.cols).concat(['json']);
    sh.getRange(1, 1, 1, head.length).setValues([head]).setFontWeight('bold');
    sh.setFrozenRows(1);
  } else if (String(sh.getRange(1, 2).getValue()) !== 'user') {
    sh.insertColumnAfter(1);
    sh.getRange(1, 2).setValue('user').setFontWeight('bold');
  }
  return sh;
}

function verKey_(email) { return 'VER_' + email; }
function version_(email) { return Number(PropertiesService.getScriptProperties().getProperty(verKey_(email || OWNER_EMAIL)) || 0); }
function bump_(email) { var k = verKey_(email || OWNER_EMAIL); var p = PropertiesService.getScriptProperties(); var v = Number(p.getProperty(k) || 0) + 1; p.setProperty(k, String(v)); return v; }
function rowUser_(v) { return String(v || '').toLowerCase() || OWNER_EMAIL; }

function getStateFor_(email, clientVer) {
  var v = version_(email);
  if (clientVer === v) return { changed: false, ver: v };
  var ck = 'ST3_' + Utilities.base64EncodeWebSafe(email) + '_' + v;
  var hit = cacheGet_(ck);
  if (hit) return { changed: true, ver: v, cols: hit };
  var out = {};
  Object.keys(STATE_TABS).forEach(function (col) {
    var sh = stateSheet_(col); var vals = sh.getDataRange().getValues(); var head = vals[0];
    var j = head.indexOf('json'); var m = {};
    for (var r = 1; r < vals.length; r++) {
      var id = String(vals[r][0]); if (!id || rowUser_(vals[r][1]) !== email) continue;
      try { m[id] = JSON.parse(vals[r][j]); } catch (e) {}
    }
    out[col] = m;
  });
  var cols = JSON.stringify(out);
  cachePut_(ck, cols, 21600);
  return { changed: true, ver: v, cols: cols };
}
/* Chunked CacheService helpers (each cache value is limited to 100 KB). */
function cachePut_(key, s, ttl) {
  var put = {}, n = Math.max(1, Math.ceil(s.length / 90000));
  for (var i = 0; i < n; i++) put[key + '_' + i] = s.substr(i * 90000, 90000);
  put[key] = String(n);
  try { CacheService.getScriptCache().putAll(put, ttl); } catch (e) {}
}
function cacheGet_(key) {
  try {
    var c = CacheService.getScriptCache(), n = Number(c.get(key) || 0); if (!n) return null;
    var ks = []; for (var i = 0; i < n; i++) ks.push(key + '_' + i);
    var g = c.getAll(ks), parts = ks.map(function (k) { return g[k]; });
    return parts.every(function (x) { return x != null; }) ? parts.join('') : null;
  } catch (e) { return null; }
}

function setDocFor_(email, col, id, json, by) {
  var lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    var def = STATE_TABS[col]; var sh = stateSheet_(col);
    var data = json === null ? null : JSON.parse(json);
    var rowNum = 0, last = sh.getLastRow();
    if (last > 1) {
      var keys = sh.getRange(2, 1, last - 1, 2).getValues();
      for (var r = 0; r < keys.length; r++) if (String(keys[r][0]) === String(id) && rowUser_(keys[r][1]) === email) { rowNum = r + 2; break; }
    }
    if (data === null) { if (rowNum) sh.deleteRow(rowNum); logActivity_(email, (by ? (by === OWNER_EMAIL ? 'admin ' : 'parent ') : '') + 'delete', col, id); return bump_(email); }
    var row = [String(id), email, new Date()].concat(def.cols.map(function (k) {
      var v = data[k]; if (v === undefined || v === null) return '';
      if (typeof v === 'object') return JSON.stringify(v);
      return typeof v === 'string' ? v.slice(0, 2000) : v;
    })).concat([json]);
    if (rowNum) sh.getRange(rowNum, 1, 1, row.length).setValues([row]);
    else sh.appendRow(row);
    logActivity_(email, (by ? (by === OWNER_EMAIL ? 'admin ' : 'parent ') : '') + (rowNum ? 'update' : 'create'), col, id);
    return bump_(email);
  } finally { lock.releaseLock(); }
}

/* Owner's direct link (google.script.run from this project's own page) */
function getState(clientVer) { return getStateFor_(OWNER_EMAIL, clientVer); }
function setDoc(col, id, json) { return setDocFor_(OWNER_EMAIL, col, id, json); }
function logEvents(json) { logEventsFor_(OWNER_EMAIL, json); return true; }

/* ---------- API for the sign-in app ---------- */
function doPost(e) {
  var out;
  try {
    var b = JSON.parse(e.postData.contents), email;
    if (b.action === 'mjob') {                       // the RecruitDirect Mailer (sending from a family's own Google account)
      out = { result: mjRelay_(b) };
      return ContentService.createTextOutput(JSON.stringify(out)).setMimeType(ContentService.MimeType.JSON);
    }
    if (b.action === 'mintSession') {               // the sign-in app (running as the owner) after someone enters their emailed code
      out = { result: mintSession_(b) };
      return ContentService.createTextOutput(JSON.stringify(out)).setMimeType(ContentService.MimeType.JSON);
    }
    if (b.sess) email = sessEmail_(b.sess);         // signed in with an emailed code
    else if (b.idt) email = idEmail_(b.idt);        // older Google sign-in pages
    else {
      if (b.key !== API_KEY) throw new Error('Not authorized');
      email = String(b.email || '').trim().toLowerCase();
    }
    if (!/^[^@\s]+@[^@\s]+$/.test(email)) throw new Error('SIGNIN_EXPIRED: sign in to use RecruitDirect.');
    out = { result: b.action === 'appVer' ? { build: APP_BUILD } : b.action === 'whoami' ? { email: email } : b.action === 'renew' && b.sess ? { sess: renewSess_(b.sess) } : route_(email, b.action, b.args || {}) };
  } catch (err) { out = { error: String(err && err.message || err) }; }
  return ContentService.createTextOutput(JSON.stringify(out)).setMimeType(ContentService.MimeType.JSON);
}

/* ---------- email-code sign-in passes ----------
   A pass is base64url({e:email, x:expiry ms, i:issued ms}) + '.' + HMAC-SHA256 signature.
   The signing key is generated by the server itself and kept in Script Properties (SESS_KEY). */
var SESS_DAYS = 365;   // stay signed in: each time the app opens, the pass is renewed for another year
function b64u_(bytes) { return Utilities.base64EncodeWebSafe(bytes).replace(/=+$/, ''); }
function sessKey_() {
  var props = PropertiesService.getScriptProperties(), k = props.getProperty('SESS_KEY');
  if (k) return k;
  var lock = LockService.getScriptLock(); lock.waitLock(10000);
  try {
    k = props.getProperty('SESS_KEY');
    if (!k) { k = (Utilities.getUuid() + Utilities.getUuid() + Utilities.getUuid()).replace(/-/g, ''); props.setProperty('SESS_KEY', k); }
  } finally { lock.releaseLock(); }
  return k;
}
function sessSig_(body) { return b64u_(Utilities.computeHmacSha256Signature(body, sessKey_())); }
function mintSession_(b) {
  var who = idEmail_(b.idt);
  if (who !== OWNER_EMAIL) throw new Error('Not authorized');
  var em = String((b.args || {}).email || '').trim().toLowerCase();
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em) || em.length > 200) throw new Error('Enter a valid email address.');
  var now = Date.now();
  var body = b64u_(Utilities.newBlob(JSON.stringify({ e: em, x: now + SESS_DAYS * 864e5, i: now })).getBytes());
  return { sess: body + '.' + sessSig_(body), email: em };
}
function renewSess_(t) {   // same person, same original sign-in time, 30 more days
  var part = String(t).split('.')[0];
  var p = JSON.parse(Utilities.newBlob(Utilities.base64DecodeWebSafe(part + '==='.slice((part.length + 3) % 4))).getDataAsString());
  var now = Date.now(), body = b64u_(Utilities.newBlob(JSON.stringify({ e: String(p.e).toLowerCase(), x: now + SESS_DAYS * 864e5, i: p.i || now })).getBytes());
  return body + '.' + sessSig_(body);
}
function sessEmail_(t) {
  t = String(t || ''); var parts = t.split('.');
  if (parts.length !== 2 || t.length > 1000) throw new Error('SIGNIN_EXPIRED: sign in again.');
  var want = sessSig_(parts[0]), got = parts[1], diff = want.length ^ got.length;
  for (var i = 0; i < want.length; i++) diff |= want.charCodeAt(i) ^ (got.charCodeAt(i) || 0);
  if (diff) throw new Error('SIGNIN_EXPIRED: sign in again.');
  var p; try { p = JSON.parse(Utilities.newBlob(Utilities.base64DecodeWebSafe(parts[0] + '==='.slice((parts[0].length + 3) % 4))).getDataAsString()); } catch (e) { throw new Error('SIGNIN_EXPIRED: sign in again.'); }
  if (!p || !p.e || !(p.x > Date.now())) throw new Error('SIGNIN_EXPIRED: your sign-in ran out. Sign in again.');
  var gen = Number(PropertiesService.getScriptProperties().getProperty('SESS_SINCE') || 0);   // set this to sign everyone out
  if (gen && p.i < gen) throw new Error('SIGNIN_EXPIRED: sign in again.');
  return String(p.e).toLowerCase();
}

/* Checks a Google identity token from the sign-in app and returns the signed-in email.
   The token's audience (the sign-in app's Google client) is pinned the first time the owner signs in. */
function idEmail_(idt) {
  idt = String(idt || '');
  if (idt.split('.').length !== 3 || idt.length > 4096) throw new Error('SIGNIN_EXPIRED: sign in again.');
  var cache = CacheService.getScriptCache();
  var key = 'idt_' + Utilities.base64EncodeWebSafe(Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, idt)).slice(0, 43);
  var hit = cache.get(key); if (hit) return hit;
  var r = UrlFetchApp.fetch('https://oauth2.googleapis.com/tokeninfo?id_token=' + encodeURIComponent(idt), { muteHttpExceptions: true });
  if (r.getResponseCode() !== 200) throw new Error('SIGNIN_EXPIRED: your sign-in timed out.');
  var t = JSON.parse(r.getContentText());
  if (!/^(https:\/\/)?accounts\.google\.com$/.test(String(t.iss)) || String(t.email_verified) !== 'true' || !t.email) throw new Error('SIGNIN_EXPIRED: sign in again.');
  var em = String(t.email).toLowerCase(), props = PropertiesService.getScriptProperties(), aud = props.getProperty('ID_AUD');
  if (!aud) {
    if (em !== OWNER_EMAIL) throw new Error('RecruitDirect is finishing an update. Try again in a few minutes.');
    props.setProperty('ID_AUD', String(t.aud)); aud = String(t.aud);
  }
  if (String(t.aud) !== aud) throw new Error('SIGNIN_EXPIRED: sign in again.');
  var left = Number(t.exp) - Math.floor(Date.now() / 1000) - 60;
  if (left > 30) cache.put(key, em, Math.min(left, 3000));
  return em;
}

function route_(email, action, a) {
  pfGate_(email, action, a);
  pfBillGate_(email, action, a);
  switch (action) {
    case 'boot':
      var t0 = Date.now();
      if (!ss_().getSheetByName('Coaches')) setup();
      if (a.packed) {
        var pk = seedPacked_(a.sport);
        var res = { h: pk.h, user: { email: email, owner: email === OWNER_EMAIL } };
        if (a.h !== pk.h) res.seedGz = pk.gz;
        if (a.plain) res.seed = Utilities.ungzip(Utilities.newBlob(Utilities.base64Decode(pk.gz), 'application/x-gzip')).getDataAsString('UTF-8');
        if (a.state) res.state = pfCoach_(email) ? { changed: true, ver: 0, cols: '{}' } : getStateFor_(email, -1);
        recordSignIn_(email, Date.now() - t0, a.h === pk.h ? 'sign-in app (cached)' : 'sign-in app');
        return res;
      }
      var seed = seedJson_();
      recordSignIn_(email, Date.now() - t0, 'sign-in app');
      return { seed: seed, user: { email: email, owner: email === OWNER_EMAIL } };
    case 'getState': return pfCoach_(email) ? { changed: a.ver === -1, ver: a.ver === -1 ? 0 : a.ver, cols: a.ver === -1 ? '{}' : undefined } : getStateFor_(email, a.ver);
    case 'setDoc': if (pfCoach_(email)) return a.ver || 0; return setDocFor_(email, a.col, a.id, a.json === undefined ? null : a.json);
    case 'ask': return ask(a.input);
    case 'log': logEventsFor_(email, a.events); return true;
    case 'xStatus': return pfCoach_(email) ? { configured: false } : xStatusFor_(email);
    case 'xStart': return xStartFor_(email, a.aid);
    case 'xCallback': return xCallbackFor_(email, a.code, a.state);
    case 'xSync': return xSyncFor_(email);
    case 'xSend': return xSendFor_(email, a);
    case 'xDisconnect': return xDisconnectFor_(email);
    case 'pf': return pfFor_(email, a.op, a.a || {});
    case 'schedCreate': return schedCreate_(email, a);
    case 'schedList': return schedList_(email);
    case 'schedUpdate': return schedUpdate_(email, a);
    default: throw new Error('Unknown action ' + action);
  }
}

