function tz_() { return Session.getScriptTimeZone() || 'America/Chicago'; }
function recordSignIn_(email, ms, source) {
  try {
    var now = new Date();
    analyticsSheet_('Logins').appendRow([now, email, Utilities.formatDate(now, tz_(), 'yyyy-MM-dd'), Number(Utilities.formatDate(now, tz_(), 'H')), ms, source]);
    var lock = LockService.getScriptLock(); lock.waitLock(10000);
    try {
      var us = analyticsSheet_('Users'); var last = us.getLastRow(); var row = 0;
      if (last > 1) { var em = us.getRange(2, 1, last - 1, 1).getValues(); for (var i = 0; i < em.length; i++) if (String(em[i][0]).toLowerCase() === email) { row = i + 2; break; } }
      if (row) { var n = Number(us.getRange(row, 4).getValue() || 0) + 1; us.getRange(row, 3, 1, 2).setValues([[now, n]]); }
      else {
        us.appendRow([email, now, now, 1, email === OWNER_EMAIL ? 'yes' : '']);
