      return [t, email, Utilities.formatDate(t, tz_(), 'yyyy-MM-dd'), String(x.type || '').slice(0, 40), String(x.detail || '').slice(0, 300), x.ms === '' || x.ms == null ? '' : Number(x.ms), String(x.dev || ''), String(x.scr || ''), String(x.vp || ''), String(x.ua || '').slice(0, 200)];
    });
    var sh = analyticsSheet_('Events');
    sh.getRange(sh.getLastRow() + 1, 1, rows.length, rows[0].length).setValues(rows);
