/* ---------- AI reply assistant (optional) ---------- */
function setting_(name) {
  var sh = ss_().getSheetByName('Settings'); if (!sh) return '';
  var v = sh.getDataRange().getValues();
  for (var i = 0; i < v.length; i++) if (String(v[i][0]).indexOf(name) === 0) return String(v[i][1]).trim();
  return '';
}

function ask(inputJson) {
  var key = setting_('Anthropic API key');
  if (!key) return { text: 'The AI assistant is off in the Google Sheets version. To turn it on, paste an Anthropic API key into the Settings tab of the spreadsheet (row "Anthropic API key"). Until then, use the reply templates on the right.' };
  var msgs = JSON.parse(inputJson), merged = [];
  msgs.forEach(function (m) {
    var last = merged[merged.length - 1];
    if (last && last.role === m.role) last.content += '\n\n' + m.content; else merged.push({ role: m.role, content: String(m.content) });
  });
  if (merged.length && merged[0].role !== 'user') merged.unshift({ role: 'user', content: '(start)' });
  var res = UrlFetchApp.fetch('https://api.anthropic.com/v1/messages', {
    method: 'post', contentType: 'application/json', muteHttpExceptions: true,
    headers: { 'x-api-key': key, 'anthropic-version': '2023-06-01' },
    payload: JSON.stringify({ model: setting_('Claude model') || 'claude-sonnet-5-5', max_tokens: 1200, messages: merged })
  });
  var code = res.getResponseCode(), body = JSON.parse(res.getContentText() || '{}');
  if (code >= 300) return { text: 'The AI assistant could not answer (' + code + (body.error && body.error.message ? ': ' + body.error.message : '') + '). Check the API key and model in the Settings tab.' };
  return { text: (body.content || []).filter(function (b) { return b.type === 'text'; }).map(function (b) { return b.text; }).join('') };
}

/* ======================================================================================
   X (Twitter) DMs. Each signed-in person can connect ONE X account with OAuth 2.0 + PKCE
   (they sign in on x.com; no password ever reaches RecruitDirect). DMs sync into their
   Messages every 15 minutes (and on "Sync now"); replies are sent through the X API.
   Needs Script Properties X_CLIENT_ID and X_CLIENT_SECRET from the X developer app,
   whose callback URL is the sign-in app link (X_CALLBACK below).
   Only unencrypted DMs are readable through X's API; encrypted XChat threads are not.
   ====================================================================================== */
var X_API = 'https://api.x.com';
var X_CALLBACK = 'https://script.google.com/macros/s/AKfycbzu8uAlONeYXlzi4Q4zBqguVye-GMZnhzJOAzeMFe6Y7R_ayAOUBxC-KTqw1f6yVVdkwg/exec';
var X_SCOPES = 'dm.read dm.write tweet.read users.read offline.access';

function xProps_() { return PropertiesService.getScriptProperties(); }
function xCfg_() {
  var p = xProps_();
  return { id: p.getProperty('X_CLIENT_ID') || '', secret: p.getProperty('X_CLIENT_SECRET') || '' };
}
function xKey_(email) { return 'XTOK_' + email; }
function xGet_(email) { var v = xProps_().getProperty(xKey_(email)); return v ? JSON.parse(v) : null; }
function xPut_(email, t) { xProps_().setProperty(xKey_(email), JSON.stringify(t)); }
function b64url_(bytes) { return Utilities.base64EncodeWebSafe(bytes).replace(/=+$/, ''); }

function xStatusFor_(email) {
  var c = xCfg_(), t = xGet_(email);
  return { configured: !!(c.id && c.secret), connected: !!(t && t.access), username: t && t.username || '',
           lastSync: t && t.lastSync || '', lastError: t && t.lastError || '' };
}

function xStartFor_(email, aid) {
  var c = xCfg_();
  if (!c.id || !c.secret) throw new Error('X is not set up yet: add X_CLIENT_ID and X_CLIENT_SECRET in the Apps Script project settings.');
  var state = Utilities.getUuid().replace(/-/g, '');
  var verifier = (Utilities.getUuid() + Utilities.getUuid()).replace(/-/g, '');
  CacheService.getScriptCache().put('XSTATE_' + state, JSON.stringify({ email: email, verifier: verifier, aid: aid || 'aj' }), 600);
  var challenge = b64url_(Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, verifier, Utilities.Charset.US_ASCII));
  var q = { response_type: 'code', client_id: c.id, redirect_uri: X_CALLBACK, scope: X_SCOPES, state: state,
            code_challenge: challenge, code_challenge_method: 'S256' };
  return { url: 'https://x.com/i/oauth2/authorize?' + Object.keys(q).map(function (k) { return k + '=' + encodeURIComponent(q[k]); }).join('&') };
}

function xToken_(params) {
  var c = xCfg_();
  params.client_id = c.id;
  var res = UrlFetchApp.fetch(X_API + '/2/oauth2/token', {
    method: 'post', muteHttpExceptions: true, payload: params,
    headers: { Authorization: 'Basic ' + Utilities.base64Encode(c.id + ':' + c.secret) } });
  var body = JSON.parse(res.getContentText() || '{}');
  if (res.getResponseCode() >= 300) throw new Error('X sign-in failed: ' + (body.error_description || body.error || res.getResponseCode()));
  return body;
}

// Called by the sign-in app when x.com redirects back with ?code&state.
function xCallbackFor_(email, code, state) {
  var cache = CacheService.getScriptCache(), raw = cache.get('XSTATE_' + state);
  if (!raw) throw new Error('This X sign-in link expired. Go back to RecruitDirect and press Connect X again.');
  cache.remove('XSTATE_' + state);
  var s = JSON.parse(raw);
  if (s.email !== email) throw new Error('Signed in to RecruitDirect as a different Google account than the one that started connecting X.');
  var tok = xToken_({ grant_type: 'authorization_code', code: code, redirect_uri: X_CALLBACK, code_verifier: s.verifier });
  var scopes = String(tok.scope || '');
  if (scopes.indexOf('dm.read') < 0 || scopes.indexOf('dm.write') < 0) throw new Error('X did not grant permission to read and send DMs.');
  var me = JSON.parse(UrlFetchApp.fetch(X_API + '/2/users/me', { headers: { Authorization: 'Bearer ' + tok.access_token }, muteHttpExceptions: true }).getContentText());
  if (!me.data) throw new Error('Could not read the connected X profile.');
  xPut_(email, { access: tok.access_token, refresh: tok.refresh_token || '', exp: Date.now() + (Number(tok.expires_in || 7200) - 120) * 1000,
                 xid: me.data.id, username: me.data.username, aid: s.aid, connectedAt: new Date().toISOString(), backfilled: false });
  xEnsureTrigger_();
  logActivity_(email, 'connect', 'x', me.data.username);
  try { xSyncFor_(email); } catch (e) {}
  return { username: me.data.username };
}

function xAccess_(email) {
  var t = xGet_(email);
  if (!t || !t.access) throw new Error('X is not connected.');
  if (Date.now() < t.exp) return t;
  var lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    t = xGet_(email);
    if (Date.now() < t.exp) return t;
    var tok;
    try { tok = xToken_({ grant_type: 'refresh_token', refresh_token: t.refresh }); }
    catch (e) { t.access = ''; t.lastError = 'X access expired or was removed. Press Connect X again.'; xPut_(email, t); throw e; }
    t.access = tok.access_token; if (tok.refresh_token) t.refresh = tok.refresh_token;
    t.exp = Date.now() + (Number(tok.expires_in || 7200) - 120) * 1000;
    xPut_(email, t);
    return t;
  } finally { lock.releaseLock(); }
}

// One X API call as the user. Returns {code, body, reset}.
function xCall_(email, method, path, body) {
  for (var attempt = 0; attempt < 2; attempt++) {
    var t = xAccess_(email);
    var opt = { method: method, muteHttpExceptions: true, headers: { Authorization: 'Bearer ' + t.access } };
    if (body) { opt.contentType = 'application/json'; opt.payload = JSON.stringify(body); }
    var res = UrlFetchApp.fetch(X_API + path, opt), code = res.getResponseCode();
    if (code === 401 && attempt === 0) { t.exp = 0; xPut_(email, t); continue; }      // token died early: refresh once
    var h = res.getHeaders();
    return { code: code, body: JSON.parse(res.getContentText() || '{}'), reset: Number(h['x-rate-limit-reset'] || h['X-Rate-Limit-Reset'] || 0) };
  }
}

function xErr_(r) {
  if (r.code === 429) return 'X limit reached. Try again after ' + (r.reset ? Utilities.formatDate(new Date(r.reset * 1000), tz_(), 'h:mm a') : 'a few minutes') + '.';
  if (r.code === 403) return 'X refused it. The coach may not accept DMs from this account.';
  if (r.code === 404) return 'That X account was not found.';
  var b = r.body || {};
  return 'X error ' + r.code + (b.detail ? ': ' + b.detail : b.title ? ': ' + b.title : '');
}

// X user id <-> username cache (saves paid user lookups).
function xUsers_() { var v = xProps_().getProperty('XUSERS'); return v ? JSON.parse(v) : {}; }
function xSaveUsers_(m) { var keys = Object.keys(m); if (keys.length > 3000) keys.slice(0, keys.length - 3000).forEach(function (k) { delete m[k]; }); xProps_().setProperty('XUSERS', JSON.stringify(m)); }

// Directory coaches by X handle (lowercase, no @) -> {id, n, s}; same ids the app uses.
function xCoachByHandle_() {
  var cache = CacheService.getScriptCache(), hit = cache.get('XHANDLES');
  if (hit) return JSON.parse(hit);
  var rows = rowsAsObjects_(ss_().getSheetByName('Coaches'), COACH_COLS).filter(function (c) { return c.n && c.s; });
  var seen = {}, map = {};
  rows.forEach(function (c) {
    if (!c.id) c.id = slug_(c.s).slice(0, 34) + '--' + slug_(c.n);
    while (seen[c.id]) c.id += '-x';
    seen[c.id] = 1;
    if (c.x && c.cs !== 'departed') map[String(c.x).replace(/^@/, '').toLowerCase()] = { id: c.id, n: c.n, s: c.s };
  });
  try { cache.put('XHANDLES', JSON.stringify(map), 21600); } catch (e) {}
  return map;
}

// Writes many Messages rows for one person in one pass (insert or merge), then bumps once.
function xWriteLogs_(email, docs) {
  if (!docs.length) return;
  var lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    var def = STATE_TABS.log, sh = stateSheet_('log'), last = sh.getLastRow();
    var head = sh.getRange(1, 1, 1, sh.getLastColumn()).getValues()[0], jcol = head.indexOf('json');
    var vals = last > 1 ? sh.getRange(2, 1, last - 1, head.length).getValues() : [];
    var where = {};
    vals.forEach(function (r, i) { if (rowUser_(r[1]) === email) where[String(r[0])] = i; });
    var appends = [];
    docs.forEach(function (d) {
      var data = d.data, i = where[d.id];
      if (i === -1) return;                                   // written earlier in this batch
      if (i !== undefined) { if (!d.merge) return; try { data = Object.assign(JSON.parse(vals[i][jcol]), d.merge); } catch (e) { return; } }
      if (!data) return;
      var row = [d.id, email, new Date()].concat(def.cols.map(function (k) { var v = data[k]; return v == null ? '' : typeof v === 'object' ? JSON.stringify(v) : v; })).concat([JSON.stringify(data)]);
      if (i !== undefined) sh.getRange(i + 2, 1, 1, row.length).setValues([row]);
      else { appends.push(row); where[d.id] = -1; }
    });
    if (appends.length) sh.getRange(sh.getLastRow() + 1, 1, appends.length, appends[0].length).setValues(appends);
    bump_(email);
  } finally { lock.releaseLock(); }
}

function xKnownIds_(email) {
  var sh = stateSheet_('log'), last = sh.getLastRow(), out = {};
  if (last < 2) return out;
  sh.getRange(2, 1, last - 1, 2).getValues().forEach(function (r) { if (String(r[0]).indexOf('xdm_') === 0 && rowUser_(r[1]) === email) out[String(r[0])] = 1; });
  return out;
}

// Pull new DMs (newest first) until we reach ones already stored. First run: last 30 days, up to 300.
function xSyncFor_(email) {
  var t = xGet_(email);
  if (!t || !t.access && !t.refresh) return { skipped: true };
  var known = xKnownIds_(email), users = xUsers_(), handles = xCoachByHandle_();
  var initial = !t.backfilled, pages = 0, token = '', docs = [], stop = false, sawKnown = false;
  do {
    var q = '/2/dm_events?event_types=MessageCreate&max_results=' + (initial ? 100 : 20) +
      '&dm_event.fields=id,text,sender_id,dm_conversation_id,created_at,attachments&expansions=sender_id' +
      '&user.fields=username,name' + (token ? '&pagination_token=' + encodeURIComponent(token) : '');
    var r = xCall_(email, 'get', q);
    if (r.code >= 300) { t = xGet_(email); t.lastError = xErr_(r); xPut_(email, t); throw new Error(t.lastError); }
    ((r.body.includes || {}).users || []).forEach(function (u) { users[u.id] = { u: u.username, n: u.name }; });
    (r.body.data || []).forEach(function (e) {
      var id = 'xdm_' + e.id;
      if (known[id]) {
        // Already stored. An outbound one we sent (status "sent") now shows on X: delivered.
        if (e.sender_id === t.xid) docs.push({ id: id, merge: { xstatus: 'delivered' } });
        if (!initial) sawKnown = true;
        return;
      }
      var out = e.sender_id === t.xid;
      var m = /^(\d+)-(\d+)$/.exec(e.dm_conversation_id || '');
      var peer = out ? (m ? (m[1] === t.xid ? m[2] : m[1]) : '') : e.sender_id;
      docs.push({ id: id, peer: peer, out: out, e: e });
    });
    token = (r.body.meta || {}).next_token;
    pages++;
    if (sawKnown) stop = true;                     // reached messages we already have
  } while (token && !stop && pages < (initial ? 3 : 2));

  // Resolve usernames we have not seen (paid lookup, cached).
  docs.forEach(function (d) {
    if (d.e && d.peer && !users[d.peer]) {
      var u = xCall_(email, 'get', '/2/users/' + d.peer + '?user.fields=username,name');
      if (u.code < 300 && u.body.data) users[d.peer] = { u: u.body.data.username, n: u.body.data.name };
    }
  });
  xSaveUsers_(users);

  var write = docs.map(function (d) {
