    var loadMs = Date.now() - t0; console.log('vf load ms ' + loadMs + ' (schools ' + list.length + ', cursor ' + cur + ')'); var until = t0 + Math.max(25000, Math.min(VF_RUN_MS_, 300000 - 2.2 * loadMs));
    while (cur < list.length && Date.now() < until && vfQuotaLeft_() > 60) {
