      try { st = vfSchool_(S, ctxs, D, { pc: PC }); } catch (e) { st = { pages: 0, coaches: 0, v: 0, u: 0, f: 0, n: 0, sports: [], note: ['error: ' + String(e && e.message || e).slice(0, 150)] }; }
      if (st.coaches || st.note.length) log.push([new Date(), S.n, st.sports.join(' '), st.pages, st.coaches, st.v, st.u, st.f, st.n, st.note.join('; ')]);
      ['coaches', 'v', 'u', 'f', 'n'].forEach(function (k) { tot[k] = (tot[k] || 0) + (st[k] || 0); });
