/* owner summary for one sport: counts by status and the coaches that still need a look */
function contactCheckSummary_(sport) {
  return withSport_(VF_SPORTS_.indexOf(sport) >= 0 ? sport : 'fb', function () {
    var ctx = scanContext_(SPORT_.log), H = ctx.H, c = { verified: 0, updated: 0, 'partly verified': 0, unconfirmed: 0, 'no contact': 0, unchecked: 0 }, list = [];
    ctx.vals.forEach(function (r) {
      if (String(r[H['Status']]) === 'departed') return;
      var s = H['Contact check'] === undefined ? '' : String(r[H['Contact check']] || '');
      c[s in c ? s : 'unchecked']++;
      if ((s === 'unconfirmed' || s === 'no contact' || (H['Verify note'] !== undefined && /more than one|lists |does not accept|not a valid|shared inbox/.test(String(r[H['Verify note']] || '')))) && list.length < 400)
        list.push({ s: String(r[H['School']]), n: String(r[H['Name']]), r: String(r[H['Role']] || ''), e: String(r[H['Email']] || ''), p: String(r[H['Phone']] || ''), st: s, note: String(r[H['Verify note']] || '') });
    });
    var p = PropertiesService.getScriptProperties();
    return { sport: SPORT_.key, name: SPORT_.name, counts: c, list: list, month: p.getProperty('VF_MONTH') || '', cursor: Number(p.getProperty('VF_CURSOR') || 0), done: p.getProperty('VF_DONE') === month_(), last: cellDay_(setting_('Last contact check')) };
  });
}

/* ---------- editor helpers ---------- */
function verifyInstall() {
  ScriptApp.getProjectTriggers().forEach(function (t) { if (t.getHandlerFunction() === 'verifyContacts') ScriptApp.deleteTrigger(t); });
  ScriptApp.newTrigger('verifyContacts').timeBased().everyMinutes(30).create();
  VF_SPORTS_.forEach(function (sp) { withSport_(sp, vfEnsureCols_); });
  var r = verifyContacts(); Logger.log(r);
  return 'Contact check installed: runs every 30 minutes until each month\'s pass is done. ' + r;
}
function verifyRestart() { var p = PropertiesService.getScriptProperties(); ['VF_DONE', 'VF_MONTH', 'VF_CURSOR', 'VF_TOT'].forEach(function (k) { p.deleteProperty(k); }); return verifyContacts(); }
function verifyStatus() {
  var r = VF_SPORTS_.map(function (sp) { var s = contactCheckSummary_(sp), c = s.counts; return s.name + ': ' + c.verified + ' verified, ' + c.updated + ' updated, ' + c['partly verified'] + ' partly, ' + c.unconfirmed + ' unconfirmed, ' + c['no contact'] + ' no contact, ' + c.unchecked + ' not checked yet'; });
  var p = PropertiesService.getScriptProperties();
  r.push('Pass ' + (p.getProperty('VF_MONTH') || '-') + ': school ' + (p.getProperty('VF_CURSOR') || 0) + (p.getProperty('VF_DONE') ? ' (done)' : '') + ' · fetches left today ' + vfQuotaLeft_());
  Logger.log(r.join('\n')); return r.join('\n');
}
function verifySchool(name) { var r = verifySchoolNow_('', name || 'Baylor University'); Logger.log(JSON.stringify(r, null, 1)); return r; }

/* v66: the app asks for a school's program-level contacts (all sports, or one) */
function progContacts_(a) {
  var school = String((a && a.school) || '').trim().toLowerCase(), sport = String((a && a.sport) || '');
  if (!school) return { rows: [] };
  var c = CacheService.getScriptCache(), key = 'pc_' + Utilities.base64EncodeWebSafe(school).slice(0, 200), hit = c.get(key), all;
  if (hit) all = JSON.parse(hit);
  else {
    var sh = plainSheet_('Program Contacts', VF_PC_HEAD_), last = sh.getLastRow(), vals = last > 1 ? sh.getRange(2, 1, last - 1, VF_PC_HEAD_.length).getValues() : [];
    all = vals.filter(function (r) { return String(r[0]).trim().toLowerCase() === school; })
      .map(function (r) { return { sp: String(r[1]), q: String(r[2] || ''), e: String(r[3] || ''), p: String(r[4] || ''), x: String(r[5] || ''), c: String(r[6] || ''), cp: String(r[7] || ''), at: r[8] instanceof Date ? Utilities.formatDate(r[8], 'America/Chicago', 'yyyy-MM-dd') : String(r[8] || '') }; });
    try { c.put(key, JSON.stringify(all), 3600); } catch (e) {}
  }
  return { rows: sport ? all.filter(function (r) { return r.sp === sport; }) : all };
}
